<template>
  <div class="orders-page"><AdminNav /><main>
    <header class="page-header"><div><span class="eyebrow"><i class="fa-solid fa-receipt"></i> Gestión comercial</span><h1>Pedidos y<br><em>conversaciones.</em></h1><p>Revisa cada solicitud, pago y contacto que llega desde el sitio web.</p></div><button class="refresh" @click="load"><i class="fa-solid fa-rotate"></i> Actualizar</button></header>
    <section class="order-board"><div class="board-top"><div class="filters"><button :class="{active:filter==='all'}" @click="filter='all'"><i class="fa-solid fa-layer-group"></i> Todos <b>{{ orders.length }}</b></button><button :class="{active:filter==='whatsapp'}" @click="filter='whatsapp'"><i class="fa-brands fa-whatsapp"></i> WhatsApp <b>{{ whatsappCount }}</b></button><button :class="{active:filter==='payphone'}" @click="filter='payphone'"><i class="fa-solid fa-credit-card"></i> Payphone <b>{{ payphoneCount }}</b></button></div><span>{{ filtered.length }} resultados</span></div>
      <div v-if="filtered.length" class="order-list"><article v-for="order in filtered" :key="order._id" class="order-card"><div class="source" :class="order.source"><i :class="order.source==='whatsapp' ? 'fa-brands fa-whatsapp' : 'fa-solid fa-credit-card'"></i></div><div class="customer"><div class="customer-top"><div><h2>{{ order.customerName }}</h2><span>{{ sourceLabel(order.source) }}</span></div><span class="status" :class="order.status">{{ statusLabel(order.status) }}</span></div><div class="contact"><a :href="`mailto:${order.customerEmail}`"><i class="fa-solid fa-envelope"></i>{{ order.customerEmail }}</a><a :href="phoneLink(order.customerPhone)"><i class="fa-solid fa-phone"></i>{{ order.customerPhone }}</a><span><i class="fa-solid fa-location-dot"></i>{{ order.address || 'Sin dirección' }}</span></div><div class="products"><span v-for="item in order.items" :key="item.name">{{ item.quantity }}× {{ item.name }}</span></div></div><aside><strong>${{ order.totalAmount.toFixed(2) }}</strong><time>{{ new Date(order.createdAt).toLocaleString('es-EC') }}</time><a v-if="order.source==='whatsapp'" :href="whatsAppLink(order)" target="_blank"><i class="fa-brands fa-whatsapp"></i> Abrir chat</a></aside></article></div><div v-else class="empty"><i class="fa-solid fa-filter-circle-xmark"></i><h3>No hay resultados</h3><p>Prueba con otro filtro o espera nuevas solicitudes.</p></div>
    </section>
  </main></div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import axios from 'axios'
import AdminNav from '@/components/AdminNav.vue'
import { apiBase } from '@/services/api'
interface Item { name:string; quantity:number } interface Order { _id:string; customerName:string; customerEmail:string; customerPhone:string; address:string; items:Item[]; totalAmount:number; source:'payphone'|'whatsapp'; status:string; createdAt:string }
const token=sessionStorage.getItem('admin-token')||''; const orders=ref<Order[]>([]); const filter=ref<'all'|'whatsapp'|'payphone'>('all')
const filtered=computed(()=>filter.value==='all'?orders.value:orders.value.filter(order=>order.source===filter.value)); const whatsappCount=computed(()=>orders.value.filter(order=>order.source==='whatsapp').length); const payphoneCount=computed(()=>orders.value.filter(order=>order.source==='payphone').length)
const load=async()=>{orders.value=(await axios.get(`${apiBase}/orders`,{headers:{Authorization:`Bearer ${token}`}})).data}; const sourceLabel=(source:string)=>source==='whatsapp'?'Solicitud por WhatsApp':'Pago con Payphone'; const statusLabel=(status:string)=>({paid:'Pagado',pending:'Pendiente',cancelled:'Cancelado',whatsapp:'Por contactar'}[status]||status); const phoneLink=(phone:string)=>`tel:${phone.replace(/\s/g,'')}`; const whatsAppLink=(order:Order)=>`https://wa.me/${order.customerPhone.replace(/\D/g,'').replace(/^0/,'593')}?text=${encodeURIComponent(`Hola ${order.customerName}, te escribimos desde Megaprinter sobre tu solicitud.`)}`; onMounted(load)
</script>

